import { Object3D, PlaneGeometry, Mesh } from 'three/webgpu';
import { MeshBasicNodeMaterial, texture, uv, uvTransform, vec2 } from 'three/tsl';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {{x:number,y:number,z:number}} position
 * @property {{x:number,y:number,z:number}} rotation
 * @property {{x:number,y:number,z:number}} scale
 * @property {Array<{name:string,params:any}>} cinematicPrimitives
 * @property {string} imageUrl
 * @property {{x:number,y:number,w:number,h:number}} atlasRegion
 */

/**
 * @typedef {Object} NodeContext
 * @property {Object} textureLoader – sync loader returning a THREE.Texture
 * @property {Object} primitives – map of primitive functions
 */

/**
 * Creates a billboard sprite node.
 */
export default function createNode(config, ctx) {
  const container = new Object3D();

  // ---- Geometry (aspect‑ratio based on atlas region) ----
  const region = config.atlasRegion || { x: 0, y: 0, w: 512, h: 320 };
  const aspect = region.w / region.h;
  const height = 1; // base height in scene units
  const width = aspect * height;
  const geometry = new PlaneGeometry(width, height);

  // ---- Texture -------------------------------------------------
  const tex = ctx.textureLoader(config.imageUrl);
  // If the atlas region does not cover the whole texture, apply UV transform.
  const uvNode = region.x === 0 && region.y === 0 && region.w === tex.image.width && region.h === tex.image.height
    ? uv()
    : uvTransform(
        uv(),
        vec2(region.x / tex.image.width, region.y / tex.image.height), // offset
        vec2(region.w / tex.image.width, region.h / tex.image.height)  // scale
      );

  // ---- Material ------------------------------------------------
  const material = new MeshBasicNodeMaterial({
    map: texture(tex).uv(uvNode)
  });

  // ---- Mesh ----------------------------------------------------
  const mesh = new Mesh(geometry, material);
  container.add(mesh);

  // ---- Placement ------------------------------------------------
  if (config.position) container.position.set(config.position.x, config.position.y, config.position.z);
  if (config.rotation) container.rotation.set(config.rotation.x, config.rotation.y, config.rotation.z);
  if (config.scale) container.scale.set(config.scale.x, config.scale.y, config.scale.z);

  // ---- Billboard behaviour (face camera) -----------------------
  container.onBeforeRender = (_, __, camera) => {
    container.quaternion.copy(camera.quaternion);
  };

  // ---- Apply cinematic primitives (if any) --------------------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === 'function') {
        fn(container, prim.params);
      }
    }
  }

  // ---- Cleanup -------------------------------------------------
  const cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (tex && typeof tex.dispose === 'function') tex.dispose();
    // kill any GSAP timelines that might have been created elsewhere
    gsap.globalTimeline.getChildren().forEach(t => t.kill());
  };

  container.userData.cleanup = cleanup;
  container.userData.handlers = {};

  return container;
}
